/* Interface opcional, disponível somente em navegadores com WebMCP. */
(()=>{const context=document.modelContext;if(!context?.registerTool)return;const life=new AbortController();window.addEventListener('pagehide',()=>life.abort(),{once:true});try{Promise.resolve(context.registerTool({name:'buscar_atividades',title:'Buscar atividades no hub',description:'Pesquisa o catálogo local por nome ou código. Não altera registros.',inputSchema:{type:'object',properties:{consulta:{type:'string'}},required:['consulta'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||typeof input.consulta!=='string')throw Error('Informe uma consulta de texto.');const q=input.consulta.toLocaleLowerCase('pt-BR');return window.HUB_CATALOG.activities.filter(a=>(a.title+' '+a.code).toLocaleLowerCase('pt-BR').includes(q)).slice(0,30).map(a=>({id:a.id,titulo:a.title,categoria:a.category,endereco:'#atividade/'+a.id}));}},{signal:life.signal})).catch(()=>{});}catch{/* Navegadores sem suporte continuam normalmente. */}})();
